window.FILM_WORK_PROMPTS={"work_id":"src-0d580442350bd5e3","records":[{"work_id":"src-0d580442350bd5e3","frame_id":"FG-377c863b7202c0c5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (942).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"画面主体为一个巨大的白色圆筒状物体，其开口处覆盖着深色网格，内部透出暗红色块，背景为模糊的灰绿色调。","analysis":"构图极度紧凑，白色圆筒占据画面绝大部分空间，呈对角线趋势。圆筒开口朝向左下方，内部可见深色网格结构，网格后方是模糊的暗红色区域。光线柔和，白色表面有轻微阴影，整体色调偏暖且带有颗粒感，景深极浅，背景完全虚化。","prompt":"低分辨率画面，主体是一个巨大的白色圆筒状物体，表面呈现哑光质感，带有轻微的污渍和折痕。圆筒开口处覆盖着深褐色的细密网格，网格后方隐约可见暗红色的模糊色块。背景为失焦的灰绿色，光线均匀柔和，整体色调偏暖，具有明显的胶片颗粒感，画面聚焦于圆筒开口的结构细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:00:01-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (942).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.526,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-3d94b393fad1e333","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-824441c5d64a09b8","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (964).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"画面主体为密集覆盖在深色六边形网格结构上的大量昆虫，它们呈不规则分布，身体带有明显的横向条纹，整体处于昏暗环境中。","analysis":"构图呈现满屏的密集纹理，无数昆虫个体散布在深色蜂窝状背景上。昆虫身体呈椭圆形，腹部可见清晰的明暗相间横纹，头部朝向各异。光线昏暗，仅昆虫背部有微弱反光，形成局部亮区，与深黑色背景形成对比，整体色调偏暗，细节模糊。","prompt":"昏暗环境下的微距视角，画面被密集的昆虫群覆盖，它们停驻在深褐色的六边形蜂窝网格上。昆虫身体呈椭圆形，腹部具有明显的黄黑相间横向条纹，背部在微弱光线下呈现反光质感。个体分布杂乱无章，大小不一，部分重叠，整体色调深沉，仅昆虫体表有零星亮色，营造出幽暗、拥挤且充满生物纹理的视觉效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:00:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (964).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.457,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-365e9f84af2e6888","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-5ea7883b19441685","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (961).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"画面主体为一名成年女性与一名幼童的上半身。女性位于右侧，身体前倾，手臂环抱幼童；幼童位于左侧，身体直立。背景为大面积暗色墙面，环境占比约三分之一。","analysis":"构图采用偏右布局，人物占据画面中心及右侧区域。可见人物上半身，女性身形在视觉上大于幼童。视角接近平视，女性头部略低。光线从右侧射入，在人物面部及发丝形成暖黄色高光，左侧及背景处于阴影中，明暗对比强烈，色彩以暖黄与深褐为主。","prompt":"低分辨率画面，暖色调。背景为大面积深褐色暗部。画面右侧一名金发成年女性，头发蓬松，身穿米黄色针织开衫，内搭深红色波点衬衫，身体向左前方倾斜，左臂环绕在幼童身后。画面左侧一名深褐色短发幼童，身穿浅蓝色荷叶边领口连衣裙，身体直立，面部朝向右前方。光线从右侧照射，照亮女性面部、发顶及幼童右侧脸颊，形成明显的明暗分界，人物轮廓清晰，整体氛围沉静。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:00:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (961).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.518,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-79b26160e7036c7e","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-af7859eb767f4590","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (942).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"画面左侧是一团巨大的明亮火焰，右侧站立着一名深色衣着的人物。背景是密集的枯树林，天空呈现灰蓝色，整体环境显得寒冷且空旷。","analysis":"构图上，左侧高耸的火焰与右侧的人物形成视觉平衡。人物仅上半身可见，身体轮廓在火光映衬下显得较暗。火焰占据了画面约三分之一的宽度，高度几乎贯穿整个画面。背景树木呈剪影状，明暗对比强烈，火光提供了主要的暖色光源，与冷色调的天空形成反差。","prompt":"低分辨率的写实画面，左侧是一团巨大的、垂直向上燃烧的明亮橙黄色火焰，火焰形态不规则且边缘模糊。右侧站立着一名身穿深色厚衣物的人物，人物轮廓在火光下显得较暗，仅能辨识出上半身及头部的大致形状。背景是密集的、没有叶子的枯树林，树干呈灰黑色剪影状。天空呈现暗淡的灰蓝色，整体色调偏冷，与火光的暖色形成对比。画面具有明显的颗粒感，光线昏暗，呈现出一种寒冷、荒凉且带有紧张感的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:00:29-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (942).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.522,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-15868df76da68904","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-6ed76fabe7bc2413","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (856).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"画面主体为巨大的灰白色石砌废墟墙体，占据背景大部分空间。前景草地上有四名身着深色传统服饰的人物，姿态各异，包括站立、蹲坐和俯身。右下方有一只白底黑斑的狗站立，旁边草地上放有深色衣物或包裹。","analysis":"构图采用高角度俯拍，将人物置于巨大的石墙背景下，突显环境的宏大与荒凉。人物在画面中占比极小，仅能辨识全身轮廓及大姿态，无法看清面部细节。光线为柔和的自然散射光，无强烈投影。色彩以石墙的灰白、草地的暗绿及人物服饰的深褐为主，色调低沉统一，呈现出一种静谧且略带压抑的视觉氛围。","prompt":"高角度俯拍视角，展现一处荒凉的户外废墟场景。背景是巨大的灰白色石砌墙体，石块粗糙且带有风化痕迹，墙体上可见方形孔洞。前景是暗绿色的草地，散落着碎石。草地上分布着四名身穿深褐色或黑色传统长袍的人物，姿态包括站立、蹲坐和弯腰俯身，人物身形在宏大背景中显得渺小。右下方有一只白底黑斑的狗站立，旁边草地上放置着深色衣物或包裹。整体光线柔和均匀，无强烈阴影，色调偏冷且饱和度低，呈现出一种沉静、压抑且带有历史感的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:00:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (856).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.528,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-77d16cdce311a59c","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-ba18a7dab4bd75fb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (942).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"一名金发人物坐在桌前，身穿深色毛衣和红色领口，右手握笔，左手按在纸上。背景是昏暗的室内墙壁，右侧有一个玻璃杯。","analysis":"画面主体为人物上半身，占据画面中心偏左位置。人物呈坐姿，身体略微前倾。光线从左侧射入，照亮人物面部和手部，右侧及背景处于阴影中，形成强烈的明暗对比。整体色调偏暖，以棕色和暗色为主，红色领口在暗色衣物中较为醒目。","prompt":"昏暗室内，一名金发人物坐在桌前，身穿深色针织毛衣，领口露出红色波点衬衫。人物右手握笔，左手按在白色纸张上，身体略微前倾。背景是粗糙的浅色墙壁，墙上挂着模糊的深色矩形物体。右侧桌面上放着一个装有白色沉淀物的玻璃杯。光线从左侧射入，照亮人物面部和手部，右侧及背景处于阴影中，整体色调偏暖，以棕色和暗色为主。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:00:39+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (942).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.475,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-581c76e6391a32fc","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-863cf7674ad2088b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (964).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"昏暗室内，一名老年男子位于画面左侧，面部被暖光照亮。他右手向前伸出，握着一盏点亮的玻璃罩油灯，灯体位于画面右侧前景，背景几乎全黑。","analysis":"画面采用非对称构图，人物面部位于左侧，油灯占据右侧前景且因距离镜头较近而显得较大。人物仅上半身可见，头部微低，视线向下。光线主要来自油灯，形成强烈的明暗对比，暖黄色的灯光照亮了人物面部轮廓和手部，其余部分隐没在深沉的阴影中，色彩层次以暗褐与暖黄为主。","prompt":"昏暗室内场景，一名老年男子位于画面左侧，面部布满皱纹，神情凝重，身穿深色衣物，领口露出白色内衬。他右手向前伸出，握着一盏点亮的玻璃罩油灯，灯体位于画面右侧前景，因距离镜头近而显得较大。暖黄色的灯光照亮了人物面部和手部，形成强烈的明暗对比，背景几乎全黑，仅能隐约辨认出右侧的木质门框轮廓。画面色调以暗褐色和暖黄色为主，光影层次丰富，营造出一种压抑而神秘的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:00:50+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (964).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.449,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d1011650bec346c9","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-397548550d21888e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (961).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"昏暗的室内空间，中央深色门框通向内部走廊，右侧立有一把深色木椅，左侧墙边放置一张带花纹软垫的长凳，远处可见窗户亮光。","analysis":"画面采用中心对称构图，门框形成视觉焦点，引导视线深入内部空间。整体色调偏黄褐，光线昏暗，仅远处窗户透入自然光，形成明暗对比。室内陈设稀疏，家具轮廓清晰，墙面大面积留白，营造出空旷、静谧且略带压抑的视觉氛围。","prompt":"昏暗的室内场景，整体色调呈黄褐色。画面中央是一个深色木质门框，门扇向内敞开，透过门洞可见内部狭长的走廊，走廊尽头有一扇透着亮光的窗户。右侧墙边立着一把深色木质靠背椅，左侧墙根处放置一张带有花纹软垫的长凳。墙面大面积留白，光线微弱，仅远处有亮光，营造出空旷、静谧且略带压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:01:00+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (961).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.518,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8267c9f0e48e59d6","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-ef690230c876e740","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (935).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"夜间户外，一名穿深色条纹披肩的成年人跪在左侧，面向右侧坐在地上的儿童。两人面前有一堆明亮的火焰，背景是黑暗中的模糊箱状物体。","analysis":"画面主体为前景的两人及火焰，背景环境占比约三分之一。成年人呈跪姿，身体前倾，儿童盘腿而坐，两人均可见上半身及腿部轮廓。火焰位于画面下方中央，是主要光源，照亮人物面部及衣物局部，形成强烈的明暗对比。背景处于暗部，仅能辨识出堆叠的箱状轮廓。","prompt":"夜间户外场景，低分辨率画面。前景左侧一名成年人跪姿，身披深褐色带浅色波浪纹的披肩，身体前倾面向右侧。右侧一名儿童盘腿坐在地面，身穿深色上衣，领口露出浅色内衬。两人之间下方有一堆明亮的橙黄色火焰，火焰向上燃烧，照亮人物面部及衣物局部。背景为黑暗环境，隐约可见堆叠的箱状物体轮廓。整体色调偏暗，以火焰的暖色光与周围冷暗色形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:01:10+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (935).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.521,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-28f61ac311feb08f","origin":"visual"},{"work_id":"src-0d580442350bd5e3","frame_id":"FG-c898c8a25aacc826","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (847).jpg","source_page":"https://film-grab.com/2013/02/20/spirit-of-the-beehive/","scene":"昏暗的室内空间，并排摆放着两张带有绿色雕花床头板的旧式木床。左侧床铺空置，右侧床铺铺有白色床单。两床之间夹着一个深色木柜，墙上挂有一幅深色画作，左侧有一扇黑色的门。","analysis":"画面采用平视视角，构图对称。两张床占据了画面的主要宽度，床头的绿色雕花板在暗色背景中较为突出。光线从左侧射入，在木地板上投下明显的阴影，照亮了左侧床架和部分地面。整体色调偏暖黄与深褐，明暗对比强烈，营造出一种陈旧、静谧且略带压抑的视觉氛围。","prompt":"昏暗陈旧的室内场景，平视视角。画面中央并排摆放着两张老式木床，床头板为绿色雕花设计，造型独特。左侧床铺空置，露出木质床板；右侧床铺铺着白色床单，略显凌乱。两床之间放置一个深色木质床头柜，上面摆放着模糊的小物件。背景墙面呈土黄色，正中挂着一幅深色调的人物画作。画面左侧是一扇漆黑的门洞，右侧边缘可见一个深色木柜。光线从左侧射入，在浅色木地板上投下长长的阴影，照亮了左侧床架。整体色调为暖黄与深褐，光影对比强烈，呈现出一种静谧、压抑且充满年代感的视觉风格。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:01:22+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (847).jpg","observed_dimensions":[783,480],"source_thumbnail_dimensions":[500,307],"source_image_match_mae":0.53,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-ecdfda868f375bca","origin":"visual"}]};